      userId: 'user_001',
      front: 'How do useEffect dependencies work and what are common pitfalls?',
      back: "useEffect dependencies determine when the effect runs. The dependency array compares values with Object.is (same as ===). Common pitfalls include missing dependencies, infinite loops, and stale closures.\n\nExample:\n```javascript\n// Basic useEffect with dependencies\nuseEffect(() => {\n  // This runs when component mounts AND when count changes\n  document.title = `Count: ${count}`;\n}, [count]); // Dependency array\n\n// Missing dependencies (pitfall)\nuseEffect(() => {\n  // eslint-disable-next-line react-hooks/exhaustive-deps\n  fetchData(userId); // WARNING: userId not in dependencies\n}, []); // This will use stale userId if it changes\n\n// Correct way\nuseEffect(() => {\n  fetchData(userId);\n}, [userId]);\n\n// Infinite loop pitfall\nuseEffect(() => {\n  setCount(count + 1); // Updates count, which triggers this effect again\n}, [count]); // INFINITE LOOP!\n\n// Object/array dependency pitfall\nuseEffect(() => {\n  console.log('Config changed');\n}, [config]); // config is an object - effect runs on every render!\n\n// Solutions:\n// 1. Use primitive values in dependencies\nuseEffect(() => {\n  console.log('User ID changed');\n}, [userId]); // Good - primitive\n\n// 2. Use useMemo for objects\nconst memoizedConfig = useMemo(() => config, [config.value1, config.value2]);\nuseEffect(() => {\n  console.log('Config changed');\n}, [memoizedConfig]); // Better\n\n// 3. Use callback ref for functions\nconst fetchData = useCallback(() => {\n  // fetch logic\n}, [userId]);\n\nuseEffect(() => {\n  fetchData();\n}, [fetchData]); // Good - stable reference\n\n// Cleanup function\nuseEffect(() => {\n  const subscription = api.subscribe(id);\n  \n  return () => {\n    subscription.unsubscribe(); // Cleanup on unmount or when id changes\n  };\n}, [id]);\n```",
