      front:
        'What are custom hooks and how do you create reusable logic with them?',
      back: "Custom hooks are JavaScript functions that use React hooks internally. They allow extracting and reusing stateful logic across components.\n\nExample:\n```javascript\n// Custom hook: useLocalStorage\nfunction useLocalStorage(key, initialValue) {\n  // State to store our value\n  const [storedValue, setStoredValue] = useState(() => {\n    try {\n      const item = window.localStorage.getItem(key);\n      return item ? JSON.parse(item) : initialValue;\n    } catch (error) {\n      console.error(error);\n      return initialValue;\n    }\n  });\n  \n  // Return a wrapped version of useState's setter\n  const setValue = (value) => {\n    try {\n      // Allow value to be a function\n      const valueToStore = value instanceof Function ? value(storedValue) : value;\n      \n      setStoredValue(valueToStore);\n      \n      // Save to localStorage\n      window.localStorage.setItem(key, JSON.stringify(valueToStore));\n    } catch (error) {\n      console.error(error);\n    }\n  };\n  \n  return [storedValue, setValue];\n}\n\n// Custom hook: useFetch\nfunction useFetch(url, options = {}) {\n  const [data, setData] = useState(null);\n  const [error, setError] = useState(null);\n  const [loading, setLoading] = useState(true);\n  \n  useEffect(() => {\n    const fetchData = async () => {\n      try {\n        setLoading(true);\n        const response = await fetch(url, options);\n        \n        if (!response.ok) {\n          throw new Error(`HTTP ${response.status}`);\n        }\n        \n        const result = await response.json();\n        setData(result);\n        setError(null);\n      } catch (err) {\n        setError(err);\n      } finally {\n        setLoading(false);\n      }\n    };\n    \n    fetchData();\n    \n    // Cleanup function\n    return () => {\n      // Cancel fetch if component unmounts\n    };\n  }, [url, JSON.stringify(options)]); // Re-run when url or options change\n  \n  return { data, error, loading, refetch: () => {\n    // Trigger re-fetch\n    const controller = new AbortController();\n    options.signal = controller.signal;\n    fetchData();\n  }};\n}\n\n// Custom hook: usePrevious\nfunction usePrevious(value) {\n  const ref = useRef();\n  \n  useEffect(() => {\n    ref.current = value;\n  }, [value]); // Only re-run if value changes\n  \n  return ref.current; // Return previous value\n}\n\n// Custom hook: useDebounce\nfunction useDebounce(value, delay) {\n  const [debouncedValue, setDebouncedValue] = useState(value);\n  \n  useEffect(() => {\n    const timer = setTimeout(() => {\n      setDebouncedValue(value);\n    }, delay);\n    \n    return () => {\n      clearTimeout(timer);\n    };\n  }, [value, delay]);\n  \n  return debouncedValue;\n}\n\n// Usage in component\nfunction UserProfile({ userId }) {\n  const { data: user, loading, error } = useFetch(`/api/users/${userId}`);\n  const [theme, setTheme] = useLocalStorage('theme', 'light');\n  const prevUserId = usePrevious(userId);\n  \n  if (loading) return <div>Loading...</div>;\n  if (error) return <div>Error: {error.message}</div>;\n  \n  return (\n    <div>\n      <h1>{user.name}</h1>\n      <p>Previous user ID: {prevUserId}</p>\n    </div>\n  );\n}\n\n// Custom hook with context\nfunction useAuth() {\n  const context = useContext(AuthContext);\n  \n  if (!context) {\n    throw new Error('useAuth must be used within an AuthProvider');\n  }\n  \n  return context;\n}\n```",
