      front:
        'How does useMemo optimize performance and when should you use it?',
      back: "useMemo memoizes expensive computations, preventing recalculation on every render. Use it for: expensive calculations, referential equality, and preventing child re-renders.\n\nExample:\n```javascript\n// Without useMemo - recalculation on every render\nfunction ExpensiveComponent({ items, filter }) {\n  // This runs on EVERY render\n  const filteredItems = items.filter(item => \n    item.name.includes(filter)\n  );\n  \n  return <ItemList items={filteredItems} />;\n}\n\n// With useMemo - only recalculates when dependencies change\nfunction OptimizedComponent({ items, filter }) {\n  const filteredItems = useMemo(() => {\n    console.log('Filtering items...'); // Only logs when items or filter changes\n    return items.filter(item => item.name.includes(filter));\n  }, [items, filter]); // Dependency array\n  \n  return <ItemList items={filterItems} />;\n}\n\n// Preventing child re-renders\nfunction ParentComponent({ user, config }) {\n  const memoizedConfig = useMemo(() => ({\n    ...config,\n    userId: user.id,\n    // Complex transformation\n    permissions: calculatePermissions(user.role)\n  }), [user, config]);\n  \n  return <ChildComponent config={memoizedConfig} />;\n}\n\n// ChildComponent won't re-render unless user or config changes\nconst ChildComponent = React.memo(({ config }) => {\n  console.log('Child rendered'); // Only when config reference changes\n  return <div>{JSON.stringify(config)}</div>;\n});\n\n// Complex calculation example\nfunction FibonacciComponent({ n }) {\n  const fibonacci = useMemo(() => {\n    console.log(`Calculating Fibonacci(${n})`);\n    \n    const fib = (num) => {\n      if (num <= 1) return num;\n      return fib(num - 1) + fib(num - 2);\n    };\n    \n    return fib(n);\n  }, [n]); // Only recalculates when n changes\n  \n  return <div>Fibonacci({n}) = {fibonacci}</div>;\n}\n\n// When NOT to use useMemo:\n// 1. Simple calculations\nconst x = useMemo(() => a + b, [a, b]); // ❌ Overkill\nconst x = a + b; // ✅ Simple enough\n\n// 2. Creating objects/arrays for effects\nuseEffect(() => {\n  // ❌ Creates new array every render anyway\n  const options = { method: 'POST', body: JSON.stringify(data) };\n  fetch(url, options);\n}, [url, data]);\n\n// 3. For side effects\nconst fetchData = useMemo(() => async () => {\n  const response = await fetch(url); // ❌ This is a side effect\n  return response.json();\n}, [url]);\n\n// Use useCallback instead:\nconst fetchData = useCallback(async () => {\n  const response = await fetch(url);\n  return response.json();\n}, [url]);\n\n// Performance measurement\nfunction MeasuredComponent({ data }) {\n  const startTime = performance.now();\n  \n  const processedData = useMemo(() => {\n    // Expensive processing\n    return data.map(item => ({\n      ...item,\n      score: calculateScore(item),\n      category: classifyItem(item)\n    }));\n  }, [data]);\n  \n  const endTime = performance.now();\n  console.log(`Processing took ${endTime - startTime}ms`);\n  \n  return <DataDisplay data={processedData} />;\n}\n```",
