      front:
        'What is React.memo and how does it prevent unnecessary re-renders?',
      back: "React.memo is a higher-order component that memoizes functional components, preventing re-renders when props haven't changed (shallow comparison).\n\nExample:\n```jsx\n// Without React.memo - re-renders on every parent render\nconst UserProfile = ({ user, onUpdate }) => {\n  console.log('UserProfile rendered'); // Logs on every parent render\n  \n  return (\n    <div>\n      <h2>{user.name}</h2>\n      <p>{user.email}</p>\n      <button onClick={() => onUpdate(user.id)}>Update</button>\n    </div>\n  );\n};\n\n// With React.memo - only re-renders when props change\nconst MemoizedUserProfile = React.memo(({ user, onUpdate }) => {\n  console.log('MemoizedUserProfile rendered'); // Only when props change\n  \n  return (\n    <div>\n      <h2>{user.name}</h2>\n      <p>{user.email}</p>\n      <button onClick={() => onUpdate(user.id)}>Update</button>\n    </div>\n  );\n});\n\n// Custom comparison function\nconst DeepComparisonProfile = React.memo(\n  ({ user, onUpdate }) => {\n    console.log('DeepComparisonProfile rendered');\n    \n    return (\n      <div>\n        <h2>{user.name}</h2>\n        <p>{user.email}</p>\n      </div>\n    );\n  },\n  // Custom comparison function (prevProps, nextProps)\n  (prevProps, nextProps) => {\n    // Deep comparison of user object\n    return (\n      prevProps.user.id === nextProps.user.id &&\n      prevProps.user.name === nextProps.user.name &&\n      prevProps.user.email === nextProps.user.email\n    );\n  }\n);\n\n// Parent component\nfunction UserList({ users }) {\n  const [count, setCount] = useState(0);\n  \n  const handleUpdate = useCallback((userId) => {\n    console.log('Update user:', userId);\n  }, []); // Stable reference\n  \n  return (\n    <div>\n      <button onClick={() => setCount(count + 1)}>\n        Rerender Parent ({count})\n      </button>\n      \n      {users.map(user => (\n        <MemoizedUserProfile\n          key={user.id}\n          user={user}\n          onUpdate={handleUpdate} // Must be stable!\n        />\n      ))}\n    </div>\n  );\n}\n\n// Common pitfall: passing new object/function\nfunction ProblematicParent() {\n  return (\n    <MemoizedUserProfile\n      user={{ id: 1, name: 'John' }} // New object every render\n      onUpdate={() => console.log('update')} // New function every render\n    />\n  );\n  // ❌ MemoizedUserProfile re-renders every time!\n}\n\n// Solution: useMemo and useCallback\nfunction OptimizedParent({ userId }) {\n  const user = useMemo(() => ({\n    id: userId,\n    name: 'John',\n    email: 'john@example.com'\n  }), [userId]);\n  \n  const handleUpdate = useCallback(() => {\n    console.log('Update');\n  }, []);\n  \n  return (\n    <MemoizedUserProfile\n      user={user} // Stable reference\n      onUpdate={handleUpdate} // Stable reference\n    />\n  );\n}\n\n// When to use React.memo:\n// 1. Pure functional components\n// 2. Components that render often\n// 3. Components with expensive render logic\n// 4. Components that re-render with same props\n\n// When NOT to use React.memo:\n// 1. Components that always get new props\n// 2. Simple components (memoization cost > benefit)\n// 3. Components with side effects in render\n\n// Testing memoization\nconst CounterDisplay = React.memo(({ count, label }) => {\n  console.log(`${label} rendered: ${count}`);\n  return <div>{label}: {count}</div>;\n});\n\nfunction TestComponent() {\n  const [count1, setCount1] = useState(0);\n  const [count2, setCount2] = useState(0);\n  \n  return (\n    <div>\n      <button onClick={() => setCount1(count1 + 1)}>\n        Increment Count 1\n      </button>\n      <button onClick={() => setCount2(count2 + 1)}>\n        Increment Count 2\n      </button>\n      \n      <CounterDisplay count={count1} label=\"Counter 1\" />\n      <CounterDisplay count={count2} label=\"Counter 2\" />\n      \n      {/* Only Counter 1 re-renders when count1 changes */}\n      {/* Only Counter 2 re-renders when count2 changes */}\n    </div>\n  );\n}\n```",
