      front:
        'How does useReducer work and when should you use it instead of useState?',
      back: "useReducer is an alternative to useState for complex state logic. It uses a reducer function (state, action) => newState and is useful for: complex state transitions, multiple sub-values, or when next state depends on previous state.\n\nExample:\n```javascript\n// Reducer function\nconst todoReducer = (state, action) => {\n  switch (action.type) {\n    case 'ADD_TODO':\n      return {\n        ...state,\n        todos: [...state.todos, {\n          id: Date.now(),\n          text: action.text,\n          completed: false\n        }]\n      };\n      \n    case 'TOGGLE_TODO':\n      return {\n        ...state,\n        todos: state.todos.map(todo =>\n          todo.id === action.id\n            ? { ...todo, completed: !todo.completed }\n            : todo\n        )\n      };\n      \n    case 'REMOVE_TODO':\n      return {\n        ...state,\n        todos: state.todos.filter(todo => todo.id !== action.id)\n      };\n      \n    case 'SET_FILTER':\n      return {\n        ...state,\n        filter: action.filter\n      };\n      \n    default:\n      return state;\n  }\n};\n\n// Initial state\nconst initialState = {\n  todos: [],\n  filter: 'all'\n};\n\n// Component using useReducer\nfunction TodoApp() {\n  const [state, dispatch] = useReducer(todoReducer, initialState);\n  \n  const filteredTodos = state.todos.filter(todo => {\n    if (state.filter === 'completed') return todo.completed;\n    if (state.filter === 'active') return !todo.completed;\n    return true;\n  });\n  \n  const addTodo = (text) => {\n    dispatch({ type: 'ADD_TODO', text });\n  };\n  \n  return (\n    <div>\n      <TodoList todos={filteredTodos} dispatch={dispatch} />\n      <AddTodo onAdd={addTodo} />\n      <FilterButtons filter={state.filter} dispatch={dispatch} />\n    </div>\n  );\n}\n\n// Lazy initialization\nfunction Counter({ initialCount }) {\n  const [state, dispatch] = useReducer(\n    counterReducer,\n    initialCount,\n    // Initializer function\n    (initialCount) => ({\n      count: initialCount,\n      history: [`Initialized with ${initialCount}`]\n    })\n  );\n  \n  return (\n    <div>\n      Count: {state.count}\n      <button onClick={() => dispatch({ type: 'INCREMENT' })}>+</button>\n      <button onClick={() => dispatch({ type: 'DECREMENT' })}>-</button>\n    </div>\n  );\n}\n\n// Action creators (optional pattern)\nconst todoActions = {\n  addTodo: (text) => ({ type: 'ADD_TODO', text }),\n  toggleTodo: (id) => ({ type: 'TOGGLE_TODO', id }),\n  removeTodo: (id) => ({ type: 'REMOVE_TODO', id })\n};\n\n// Usage with action creators\ndispatch(todoActions.addTodo('Learn useReducer'));\n\n// When to use useReducer vs useState:\n\n// ✅ useReducer is better for:\n// 1. Complex state logic with multiple sub-values\n// 2. When next state depends on previous state\n// 3. Business logic that can be tested separately\n// 4. Sharing state update logic between components\n\n// Example where useReducer shines:\nconst formReducer = (state, action) => {\n  switch (action.type) {\n    case 'CHANGE_FIELD':\n      return {\n        ...state,\n        values: {\n          ...state.values,\n          [action.field]: action.value\n        },\n        touched: {\n          ...state.touched,\n          [action.field]: true\n        }\n      };\n      \n    case 'SET_ERRORS':\n      return {\n        ...state,\n        errors: action.errors\n      };\n      \n    case 'RESET':\n      return initialState;\n      \n    default:\n      return state;\n  }\n};\n\n// With useState this becomes messy:\nfunction FormWithUseState() {\n  const [values, setValues] = useState({});\n  const [errors, setErrors] = useState({});\n  const [touched, setTouched] = useState({});\n  const [isSubmitting, setIsSubmitting] = useState(false);\n  \n  // Complex update logic scattered throughout component\n  const handleChange = (field, value) => {\n    setValues(prev => ({ ...prev, [field]: value }));\n    setTouched(prev => ({ ...prev, [field]: true }));\n    // Validate...\n  };\n}\n\n// With useReducer - all logic in one place\nfunction FormWithUseReducer() {\n  const [state, dispatch] = useReducer(formReducer, initialState);\n  \n  const handleChange = (field, value) => {\n    dispatch({ type: 'CHANGE_FIELD', field, value });\n    // Validation can be in reducer or separate effect\n  };\n}\n\n// Testing reducers (easy to unit test!)\nconst testReducer = () => {\n  const state = { count: 0 };\n  const newState = counterReducer(state, { type: 'INCREMENT' });\n  console.assert(newState.count === 1, 'Increment failed');\n};\n```",
