      front:
        'What is the Context API and how does useContext work for state management?',
      back: "Context provides a way to pass data through the component tree without prop drilling. useContext hook lets you subscribe to React context without nesting Consumers.\n\nExample:\n```jsx\n// 1. Create Context\nconst ThemeContext = React.createContext({\n  theme: 'light',\n  toggleTheme: () => {}\n});\n\nconst UserContext = React.createContext(null);\n\n// 2. Provider Component\nfunction AppProviders({ children }) {\n  const [theme, setTheme] = useState('light');\n  const [user, setUser] = useState(null);\n  \n  const toggleTheme = useCallback(() => {\n    setTheme(prev => prev === 'light' ? 'dark' : 'light');\n  }, []);\n  \n  const login = useCallback((userData) => {\n    setUser(userData);\n  }, []);\n  \n  const logout = useCallback(() => {\n    setUser(null);\n  }, []);\n  \n  const themeValue = useMemo(() => ({\n    theme,\n    toggleTheme\n  }), [theme, toggleTheme]);\n  \n  const userValue = useMemo(() => ({\n    user,\n    login,\n    logout\n  }), [user, login, logout]);\n  \n  return (\n    <ThemeContext.Provider value={themeValue}>\n      <UserContext.Provider value={userValue}>\n        {children}\n      </UserContext.Provider>\n    </ThemeContext.Provider>\n  );\n}\n\n// 3. Custom hook for easier consumption\nfunction useTheme() {\n  const context = useContext(ThemeContext);\n  \n  if (!context) {\n    throw new Error('useTheme must be used within ThemeProvider');\n  }\n  \n  return context;\n}\n\nfunction useUser() {\n  const context = useContext(UserContext);\n  \n  if (!context) {\n    throw new Error('useUser must be used within UserProvider');\n  }\n  \n  return context;\n}\n\n// 4. Component using context\nfunction ThemeToggle() {\n  const { theme, toggleTheme } = useTheme();\n  \n  return (\n    <button onClick={toggleTheme}>\n      Switch to {theme === 'light' ? 'dark' : 'light'} mode\n    </button>\n  );\n}\n\nfunction UserProfile() {\n  const { user, logout } = useUser();\n  const { theme } = useTheme();\n  \n  if (!user) {\n    return <div>Please log in</div>;\n  }\n  \n  return (\n    <div className={`profile profile-${theme}`}>\n      <h2>Welcome, {user.name}</h2>\n      <p>Email: {user.email}</p>\n      <button onClick={logout}>Logout</button>\n    </div>\n  );\n}\n\n// 5. Performance considerations\n// ❌ Bad: Value changes on every render\nfunction BadProvider({ children }) {\n  const [count, setCount] = useState(0);\n  \n  return (\n    <MyContext.Provider value={{ count, setCount }}>\n      {children}\n    </MyContext.Provider>\n  );\n  // New object every render -> all consumers re-render\n}\n\n// ✅ Good: Memoized value\nfunction GoodProvider({ children }) {\n  const [count, setCount] = useState(0);\n  \n  const value = useMemo(() => ({\n    count,\n    setCount\n  }), [count]); // Only changes when count changes\n  \n  return (\n    <MyContext.Provider value={value}>\n      {children}\n    </MyContext.Provider>\n  );\n}\n\n// 6. Multiple contexts\nfunction Header() {\n  return (\n    <header>\n      <ThemeToggle />\n      <UserProfile />\n      <Notifications /> {/* Could use another context */}\n    </header>\n  );\n}\n\n// 7. App structure\nfunction App() {\n  return (\n    <AppProviders>\n      <div className=\"App\">\n        <Header />\n        <MainContent />\n        <Footer />\n      </div>\n    </AppProviders>\n  );\n}\n\n// 8. TypeScript example with default values\nconst SettingsContext = React.createContext<Settings>({\n  language: 'en',\n  notifications: true,\n  updateSetting: () => {}\n});\n\n// 9. Dynamic context\nfunction DynamicProvider({ initialTheme, children }) {\n  const [theme, setTheme] = useState(initialTheme);\n  \n  useEffect(() => {\n    // Update context when prop changes\n    setTheme(initialTheme);\n  }, [initialTheme]);\n  \n  const value = useMemo(() => ({\n    theme,\n    setTheme\n  }), [theme]);\n  \n  return (\n    <ThemeContext.Provider value={value}>\n      {children}\n    </ThemeContext.Provider>\n  );\n}\n\n// 10. Context for dependency injection\nconst ApiContext = React.createContext({\n  fetchUsers: () => Promise.resolve([]),\n  createUser: () => Promise.resolve({})\n});\n\nfunction TestProvider({ children }) {\n  const mockApi = {\n    fetchUsers: () => Promise.resolve([{ id: 1, name: 'Test' }]),\n    createUser: () => Promise.resolve({ success: true })\n  };\n  \n  return (\n    <ApiContext.Provider value={mockApi}>\n      {children}\n    </ApiContext.Provider>\n  );\n}\n\n// In tests:\n<TestProvider>\n  <UserList /> {/* Uses mock API */}\n</TestProvider>\n```",
