      userId: 'user_001',
      front: 'What are React Portals and when should you use them?',
      back: "Portals render children into a DOM node outside the parent component's hierarchy. Useful for: modals, tooltips, dropdowns, and any UI that needs to break out of container constraints.\n\nExample:\n```jsx\n// 1. Basic Portal component\nimport ReactDOM from 'react-dom';\n\nfunction Modal({ children, isOpen, onClose }) {\n  if (!isOpen) return null;\n  \n  return ReactDOM.createPortal(\n    <div className=\"modal-overlay\" onClick={onClose}>\n      <div className=\"modal-content\" onClick={(e) => e.stopPropagation()}>\n        {children}\n        <button onClick={onClose}>Close</button>\n      </div>\n    </div>,\n    document.getElementById('modal-root') // Renders here\n  );\n}\n\n// 2. Tooltip with Portal\nfunction Tooltip({ text, children }) {\n  const [isVisible, setIsVisible] = useState(false);\n  const [coords, setCoords] = useState({ x: 0, y: 0 });\n  const childRef = useRef(null);\n  \n  const showTooltip = () => {\n    if (childRef.current) {\n      const rect = childRef.current.getBoundingClientRect();\n      setCoords({\n        x: rect.left + rect.width / 2,\n        y: rect.top - 10 // Position above element\n      });\n      setIsVisible(true);\n    }\n  };\n  \n  const hideTooltip = () => setIsVisible(false);\n  \n  return (\n    <>\n      {/* Child element */}\n      <span\n        ref={childRef}\n        onMouseEnter={showTooltip}\n        onMouseLeave={hideTooltip}\n      >\n        {children}\n      </span>\n      \n      {/* Tooltip portal */}\n      {isVisible && ReactDOM.createPortal(\n        <div\n          className=\"tooltip\"\n          style={{\n            position: 'fixed',\n            left: coords.x,\n            top: coords.y,\n            transform: 'translateX(-50%)'\n          }}\n        >\n          {text}\n        </div>,\n        document.getElementById('tooltip-root')\n      )}\n    </>\n  );\n}\n\n// 3. Dropdown menu with Portal (avoids overflow issues)\nfunction Dropdown({ trigger, children }) {\n  const [isOpen, setIsOpen] = useState(false);\n  const [position, setPosition] = useState({ top: 0, left: 0 });\n  const triggerRef = useRef(null);\n  \n  useEffect(() => {\n    const handleClickOutside = (event) => {\n      if (triggerRef.current && !triggerRef.current.contains(event.target)) {\n        setIsOpen(false);\n      }\n    };\n    \n    document.addEventListener('click', handleClickOutside);\n    return () => document.removeEventListener('click', handleClickOutside);\n  }, []);\n  \n  const toggleDropdown = () => {\n    if (triggerRef.current) {\n      const rect = triggerRef.current.getBoundingClientRect();\n      setPosition({\n        top: rect.bottom + window.scrollY,\n        left: rect.left + window.scrollX\n      });\n    }\n    setIsOpen(!isOpen);\n  };\n  \n  return (\n    <>\n      <div ref={triggerRef} onClick={toggleDropdown}>\n        {trigger}\n      </div>\n      \n      {isOpen && ReactDOM.createPortal(\n        <div\n          className=\"dropdown-menu\"\n          style={{\n            position: 'absolute',\n            top: position.top,\n            left: position.left\n          }}\n        >\n          {children}\n        </div>,\n        document.body // Directly to body\n      )}\n    </>\n  );\n}\n\n// 4. Notification system\nconst NotificationContext = React.createContext();\n\nfunction NotificationProvider({ children }) {\n  const [notifications, setNotifications] = useState([]);\n  \n  const addNotification = useCallback((message, type = 'info') => {\n    const id = Date.now();\n    setNotifications(prev => [...prev, { id, message, type }]);\n    \n    // Auto-remove after 5 seconds\n    setTimeout(() => {\n      setNotifications(prev => prev.filter(n => n.id !== id));\n    }, 5000);\n  }, []);\n  \n  const value = useMemo(() => ({ addNotification }), [addNotification]);\n  \n  return (\n    <NotificationContext.Provider value={value}>\n      {children}\n      \n      {/* Notification container portal */}\n      {ReactDOM.createPortal(\n        <div className=\"notification-container\">\n          {notifications.map(notification => (\n            <div key={notification.id} className={`notification ${notification.type}`}>\n              {notification.message}\n            </div>\n          ))}\n        </div>,\n        document.getElementById('notification-root')\n      )}\n    </NotificationContext.Provider>\n  );\n}\n\n// 5. Side drawer/navigation\nfunction SideDrawer({ isOpen, onClose, children }) {\n  useEffect(() => {\n    if (isOpen) {\n      document.body.style.overflow = 'hidden'; // Prevent scrolling\n    } else {\n      document.body.style.overflow = '';\n    }\n    \n    return () => {\n      document.body.style.overflow = '';\n    };\n  }, [isOpen]);\n  \n  if (!isOpen) return null;\n  \n  return ReactDOM.createPortal(\n    <>\n      <div className=\"drawer-overlay\" onClick={onClose} />\n      <div className=\"side-drawer\">\n        {children}\n      </div>\n    </>,\n    document.body\n  );\n}\n\n// 6. HTML structure\n// index.html\n/*\n<div id=\"root\"></div>\n<!-- Portal targets -->\n<div id=\"modal-root\"></div>\n<div id=\"tooltip-root\"></div>\n<div id=\"notification-root\"></div>\n*/\n\n// 7. Event bubbling through portals\n// Events bubble through the React tree, not the DOM tree\nfunction PortalEventExample() {\n  const handleClick = () => {\n    console.log('Clicked inside portal, but event bubbles to React parent');\n  };\n  \n  return (\n    <div onClick={() => console.log('Parent clicked')}>\n      <h2>Parent Component</h2>\n      \n      {ReactDOM.createPortal(\n        <button onClick={handleClick}>\n          Click me (in portal)\n        </button>,\n        document.getElementById('portal-root')\n      )}\n      \n      {/* Clicking the button logs both messages */}\n    </div>\n  );\n}\n```",
