        'How do useRef and forwardRef work for accessing DOM elements and component instances?',
      back: "useRef creates mutable object that persists across renders. forwardRef passes ref through components. Used for: DOM access, storing mutable values, and imperative handle patterns.\n\nExample:\n```jsx\n// 1. Basic useRef for DOM access\nfunction TextInputWithFocus() {\n  const inputRef = useRef(null);\n  \n  const focusInput = () => {\n    inputRef.current.focus();\n    inputRef.current.select();\n  };\n  \n  return (\n    <div>\n      <input ref={inputRef} type=\"text\" />\n      <button onClick={focusInput}>Focus input</button>\n    </div>\n  );\n}\n\n// 2. useRef for storing mutable values\nfunction Timer() {\n  const [count, setCount] = useState(0);\n  const intervalRef = useRef(null);\n  \n  const startTimer = () => {\n    if (intervalRef.current) return;\n    \n    intervalRef.current = setInterval(() => {\n      setCount(prev => prev + 1);\n    }, 1000);\n  };\n  \n  const stopTimer = () => {\n    if (intervalRef.current) {\n      clearInterval(intervalRef.current);\n      intervalRef.current = null;\n    }\n  };\n  \n  useEffect(() => {\n    return () => stopTimer(); // Cleanup on unmount\n  }, []);\n  \n  return (\n    <div>\n      <p>Count: {count}</p>\n      <button onClick={startTimer}>Start</button>\n      <button onClick={stopTimer}>Stop</button>\n    </div>\n  );\n}\n\n// 3. forwardRef for custom components\nconst FancyInput = React.forwardRef((props, ref) => {\n  const inputRef = useRef(null);\n  \n  // Merge refs if needed\n  React.useImperativeHandle(ref, () => ({\n    focus: () => {\n      inputRef.current.focus();\n    },\n    scrollIntoView: () => {\n      inputRef.current.scrollIntoView();\n    },\n    getValue: () => inputRef.current.value\n  }));\n  \n  return (\n    <input\n      {...props}\n      ref={inputRef}\n      style={{\n        padding: '10px',\n        borderRadius: '5px',\n        border: '2px solid blue'\n      }}\n    />\n  );\n});\n\n// Usage\nfunction ParentComponent() {\n  const fancyInputRef = useRef(null);\n  \n  const handleClick = () => {\n    if (fancyInputRef.current) {\n      fancyInputRef.current.focus();\n      console.log('Value:', fancyInputRef.current.getValue());\n    }\n  };\n  \n  return (\n    <div>\n      <FancyInput ref={fancyInputRef} placeholder=\"Enter text\" />\n      <button onClick={handleClick}>Focus and log value</button>\n    </div>\n  );\n}\n\n// 4. useImperativeHandle for custom instance methods\nconst VideoPlayer = React.forwardRef((props, ref) => {\n  const videoRef = useRef(null);\n  const [isPlaying, setIsPlaying] = useState(false);\n  \n  useImperativeHandle(ref, () => ({\n    play: () => {\n      videoRef.current.play();\n      setIsPlaying(true);\n    },\n    pause: () => {\n      videoRef.current.pause();\n      setIsPlaying(false);\n    },\n    togglePlay: () => {\n      if (isPlaying) {\n        videoRef.current.pause();\n        setIsPlaying(false);\n      } else {\n        videoRef.current.play();\n        setIsPlaying(true);\n      }\n    },\n    setVolume: (volume) => {\n      videoRef.current.volume = volume;\n    },\n    seek: (time) => {\n      videoRef.current.currentTime = time;\n    }\n  }), [isPlaying]);\n  \n  return (\n    <div>\n      <video\n        ref={videoRef}\n        src={props.src}\n        width=\"600\"\n        onPlay={() => setIsPlaying(true)}\n        onPause={() => setIsPlaying(false)}\n      />\n      <div>\n        <button onClick={() => ref.current?.togglePlay()}>\n          {isPlaying ? 'Pause' : 'Play'}\n        </button>\n      </div>\n    </div>\n  );\n});\n\n// 5. Measuring DOM elements\nfunction MeasurableComponent() {\n  const divRef = useRef(null);\n  const [dimensions, setDimensions] = useState({ width: 0, height: 0 });\n  \n  useEffect(() => {\n    if (divRef.current) {\n      const updateDimensions = () => {\n        const rect = divRef.current.getBoundingClientRect();\n        setDimensions({\n          width: rect.width,\n          height: rect.height\n        });\n      };\n      \n      updateDimensions();\n      \n      const resizeObserver = new ResizeObserver(updateDimensions);\n      resizeObserver.observe(divRef.current);\n      \n      return () => resizeObserver.disconnect();\n    }\n  }, []);\n  \n  return (\n    <div ref={divRef}>\n      <p>Width: {dimensions.width}px</p>\n      <p>Height: {dimensions.height}px</p>\n    </div>\n  );\n}\n\n// 6. Ref callback pattern\nfunction RefCallbackExample() {\n  const [node, setNode] = useState(null);\n  \n  const measuredRef = useCallback((node) => {\n    if (node !== null) {\n      setNode(node);\n      console.log('Node measured:', node.getBoundingClientRect());\n    }\n  }, []);\n  \n  return <div ref={measuredRef}>Measure me</div>;\n}\n\n// 7. Multiple refs\nfunction MultipleInputs() {\n  const inputRefs = useRef([]);\n  \n  const focusInput = (index) => {\n    if (inputRefs.current[index]) {\n      inputRefs.current[index].focus();\n    }\n  };\n  \n  return (\n    <div>\n      {[1, 2, 3, 4, 5].map((_, index) => (\n        <div key={index}>\n          <input\n            ref={el => inputRefs.current[index] = el}\n            placeholder={`Input ${index + 1}`}\n          />\n          <button onClick={() => focusInput(index)}>\n            Focus Input {index + 1}\n          </button>\n        </div>\n      ))}\n    </div>\n  );\n}\n\n// 8. Comparing refs with state\nfunction CounterComparison() {\n  const [count, setCount] = useState(0);\n  const countRef = useRef(0);\n  \n  const increment = () => {\n    setCount(count + 1); // Triggers re-render\n    countRef.current = countRef.current + 1; // Doesn't trigger re-render\n  };\n  \n  const logValues = () => {\n    console.log('State:', count); // Current render value\n    console.log('Ref:', countRef.current); // Latest value\n  };\n  \n  return (\n    <div>\n      <p>State count: {count}</p>\n      <p>Ref count: {countRef.current}</p>\n      <button onClick={increment}>Increment</button>\n      <button onClick={logValues}>Log Values</button>\n    </div>\n  );\n}\n```",
