      front:
        'What are React patterns: Compound Components, Render Props, and Higher-Order Components?',
      back: "These are advanced React patterns for component composition and code reuse: Compound Components share implicit state, Render Props pass rendering logic, HOCs wrap components with extra functionality.\n\nExample:\n```jsx\n// 1. Compound Components Pattern\nconst Tabs = ({ children }) => {\n  const [activeIndex, setActiveIndex] = useState(0);\n  \n  return (\n    <TabsContext.Provider value={{ activeIndex, setActiveIndex }}>\n      <div className=\"tabs\">{children}</div>\n    </TabsContext.Provider>\n  );\n};\n\nconst TabsContext = React.createContext();\n\nconst TabList = ({ children }) => {\n  const { activeIndex, setActiveIndex } = useContext(TabsContext);\n  \n  return (\n    <div className=\"tab-list\">\n      {React.Children.map(children, (child, index) =>\n        React.cloneElement(child, {\n          isActive: index === activeIndex,\n          onClick: () => setActiveIndex(index)\n        })\n      )}\n    </div>\n  );\n};\n\nconst Tab = ({ isActive, onClick, children }) => (\n  <button\n    className={`tab ${isActive ? 'active' : ''}`}\n    onClick={onClick}\n  >\n    {children}\n  </button>\n);\n\nconst TabPanels = ({ children }) => {\n  const { activeIndex } = useContext(TabsContext);\n  \n  return (\n    <div className=\"tab-panels\">\n      {React.Children.toArray(children)[activeIndex]}\n    </div>\n  );\n};\n\nconst TabPanel = ({ children }) => (\n  <div className=\"tab-panel\">{children}</div>\n);\n\n// Usage\nfunction App() {\n  return (\n    <Tabs>\n      <TabList>\n        <Tab>Tab 1</Tab>\n        <Tab>Tab 2</Tab>\n        <Tab>Tab 3</Tab>\n      </TabList>\n      <TabPanels>\n        <TabPanel>Content 1</TabPanel>\n        <TabPanel>Content 2</TabPanel>\n        <TabPanel>Content 3</TabPanel>\n      </TabPanels>\n    </Tabs>\n  );\n}\n\n// 2. Render Props Pattern\nclass MouseTracker extends React.Component {\n  state = { x: 0, y: 0 };\n  \n  handleMouseMove = (event) => {\n    this.setState({\n      x: event.clientX,\n      y: event.clientY\n    });\n  };\n  \n  render() {\n    return (\n      <div style={{ height: '100vh' }} onMouseMove={this.handleMouseMove}>\n        {this.props.render(this.state)}\n      </div>\n    );\n  }\n}\n\n// Hook version\nfunction useMousePosition() {\n  const [position, setPosition] = useState({ x: 0, y: 0 });\n  \n  useEffect(() => {\n    const handleMouseMove = (event) => {\n      setPosition({ x: event.clientX, y: event.clientY });\n    };\n    \n    window.addEventListener('mousemove', handleMouseMove);\n    return () => window.removeEventListener('mousemove', handleMouseMove);\n  }, []);\n  \n  return position;\n}\n\nfunction MouseTrackerHook({ render }) {\n  const position = useMousePosition();\n  return render(position);\n}\n\n// Usage\nfunction DisplayMousePosition() {\n  return (\n    <MouseTrackerHook\n      render={({ x, y }) => (\n        <div>\n          <h1>Mouse Position</h1>\n          <p>X: {x}, Y: {y}</p>\n        </div>\n      )}\n    />\n  );\n}\n\n// Children as function (alternative)\nfunction MouseTrackerChildren({ children }) {\n  const position = useMousePosition();\n  return children(position);\n}\n\n// Usage:\n<MouseTrackerChildren>\n  {({ x, y }) => <p>Position: {x}, {y}</p>}\n</MouseTrackerChildren>\n\n// 3. Higher-Order Component (HOC) Pattern\nfunction withLoading(WrappedComponent) {\n  return function WithLoadingComponent({ isLoading, ...props }) {\n    if (isLoading) {\n      return <div>Loading...</div>;\n    }\n    \n    return <WrappedComponent {...props} />;\n  };\n}\n\n// Hook-based HOC alternative\nfunction withDataFetching(WrappedComponent, fetchData) {\n  return function WithDataFetchingComponent(props) {\n    const [data, setData] = useState(null);\n    const [loading, setLoading] = useState(true);\n    const [error, setError] = useState(null);\n    \n    useEffect(() => {\n      const loadData = async () => {\n        try {\n          setLoading(true);\n          const result = await fetchData(props);\n          setData(result);\n        } catch (err) {\n          setError(err);\n        } finally {\n          setLoading(false);\n        }\n      };\n      \n      loadData();\n    }, [props]);\n    \n    if (loading) return <div>Loading...</div>;\n    if (error) return <div>Error: {error.message}</div>;\n    \n    return <WrappedComponent data={data} {...props} />;\n  };\n}\n\n// Usage\nconst UserProfile = ({ data }) => (\n  <div>\n    <h1>{data.name}</h1>\n    <p>{data.email}</p>\n  </div>\n);\n\nconst fetchUserData = async ({ userId }) => {\n  const response = await fetch(`/api/users/${userId}`);\n  return response.json();\n};\n\nconst UserProfileWithData = withDataFetching(UserProfile, fetchUserData);\n\n// Usage: <UserProfileWithData userId={1} />\n\n// 4. Prop Collections and Getters Pattern\nfunction useToggle(initialState = false) {\n  const [on, setOn] = useState(initialState);\n  \n  const toggle = () => setOn(!on);\n  const setOnState = (value) => setOn(value);\n  \n  // Prop collection\n  const togglerProps = {\n    onClick: toggle,\n    'aria-pressed': on,\n    role: 'switch'\n  };\n  \n  // Prop getter (more flexible)\n  const getTogglerProps = ({ onClick, ...props } = {}) => ({\n    ...togglerProps,\n    ...props,\n    onClick: (event) => {\n      onClick?.(event);\n      if (!event.defaultPrevented) {\n        toggle();\n      }\n    }\n  });\n  \n  return {\n    on,\n    toggle,\n    setOn: setOnState,\n    togglerProps, // Collection\n    getTogglerProps // Getter\n  };\n}\n\n// Usage\nfunction ToggleButton() {\n  const { on, getTogglerProps } = useToggle();\n  \n  return (\n    <button\n      {...getTogglerProps({\n        className: 'toggle-btn',\n        onClick: () => console.log('custom click handler'),\n        'data-testid': 'toggle-button'\n      })}\n    >\n      {on ? 'ON' : 'OFF'}\n    </button>\n  );\n}\n```",
