        "What are React's Suspense and Error Boundaries for handling loading and errors?",
      back: "Suspense displays fallback while waiting for async operations. Error Boundaries catch JavaScript errors in child components. Used for: code splitting, data fetching, and graceful error handling.\n\nExample:\n```jsx\n// 1. Error Boundary Component\nclass ErrorBoundary extends React.Component {\n  constructor(props) {\n    super(props);\n    this.state = { hasError: false, error: null, errorInfo: null };\n  }\n  \n  static getDerivedStateFromError(error) {\n    return { hasError: true, error };\n  }\n  \n  componentDidCatch(error, errorInfo) {\n    this.setState({ errorInfo });\n    // Log error to service\n    console.error('Error caught by boundary:', error, errorInfo);\n  }\n  \n  resetError = () => {\n    this.setState({ hasError: false, error: null, errorInfo: null });\n  };\n  \n  render() {\n    if (this.state.hasError) {\n      return (\n        <div className=\"error-boundary\">\n          <h2>Something went wrong</h2>\n          <details style={{ whiteSpace: 'pre-wrap' }}>\n            {this.state.error && this.state.error.toString()}\n            <br />\n            {this.state.errorInfo?.componentStack}\n          </details>\n          <button onClick={this.resetError}>Try again</button>\n        </div>\n      );\n    }\n    \n    return this.props.children;\n  }\n}\n\n// 2. Using Suspense for lazy loading\nconst LazyComponent = React.lazy(() => import('./HeavyComponent'));\n\nfunction App() {\n  return (\n    <ErrorBoundary>\n      <Suspense fallback={<div>Loading component...</div>}>\n        <LazyComponent />\n      </Suspense>\n    </ErrorBoundary>\n  );\n}\n\n// 3. Nested Suspense boundaries\nfunction ProfilePage() {\n  return (\n    <ErrorBoundary>\n      <Suspense fallback={<div>Loading profile...</div>}>\n        <ProfileDetails />\n        <Suspense fallback={<div>Loading posts...</div>}>\n          <ProfilePosts />\n        </Suspense>\n        <Suspense fallback={<div>Loading friends...</div>}>\n          <ProfileFriends />\n        </Suspense>\n      </Suspense>\n    </ErrorBoundary>\n  );\n}\n\n// 4. Data fetching with Suspense (experimental)\n// Resource wrapper for data fetching\nfunction createResource(promise) {\n  let status = 'pending';\n  let result;\n  \n  const suspender = promise.then(\n    (data) => {\n      status = 'success';\n      result = data;\n    },\n    (error) => {\n      status = 'error';\n      result = error;\n    }\n  );\n  \n  return {\n    read() {\n      if (status === 'pending') {\n        throw suspender; // Suspense will catch this\n      } else if (status === 'error') {\n        throw result; // Error Boundary will catch this\n      } else if (status === 'success') {\n        return result;\n      }\n    }\n  };\n}\n\n// Usage\nconst userResource = createResource(fetchUser(1));\n\nfunction UserProfile() {\n  const user = userResource.read(); // May throw to Suspense\n  \n  return (\n    <div>\n      <h1>{user.name}</h1>\n      <p>{user.email}</p>\n    </div>\n  );\n}\n\nfunction App() {\n  return (\n    <ErrorBoundary>\n      <Suspense fallback={<div>Loading user...</div>}>\n        <UserProfile />\n      </Suspense>\n    </ErrorBoundary>\n  );\n}\n\n// 5. Custom hook for data fetching with Suspense\nfunction useSuspenseFetch(url) {\n  const resource = useMemo(() => createResource(fetch(url).then(r => r.json())), [url]);\n  return resource.read();\n}\n\n// 6. Error Boundary with hook (custom implementation)\nfunction useErrorHandler(givenError) {\n  const [error, setError] = useState(null);\n  \n  if (givenError) throw givenError;\n  if (error) throw error;\n  \n  return setError;\n}\n\n// 7. Retry mechanism with Error Boundary\nclass RetryErrorBoundary extends ErrorBoundary {\n  constructor(props) {\n    super(props);\n    this.state = { ...this.state, retryCount: 0 };\n  }\n  \n  componentDidCatch(error, errorInfo) {\n    super.componentDidCatch(error, errorInfo);\n    \n    if (this.state.retryCount < this.props.maxRetries) {\n      setTimeout(() => {\n        this.setState(prev => ({\n          hasError: false,\n          error: null,\n          errorInfo: null,\n          retryCount: prev.retryCount + 1\n        }));\n      }, 1000 * Math.pow(2, this.state.retryCount)); // Exponential backoff\n    }\n  }\n  \n  render() {\n    if (this.state.hasError && this.state.retryCount >= this.props.maxRetries) {\n      return (\n        <div>\n          <h2>Failed after {this.props.maxRetries} retries</h2>\n          <button onClick={this.resetError}>Reset</button>\n        </div>\n      );\n    }\n    \n    return super.render();\n  }\n}\n\n// 8. SuspenseList for coordinating multiple Suspense boundaries\n// (Experimental - requires react experimental build)\n/*\nimport { SuspenseList } from 'react';\n\nfunction Feed() {\n  return (\n    <SuspenseList revealOrder=\"forwards\">\n      <Suspense fallback={<div>Loading profile...</div>}>\n        <ProfileDetails />\n      </Suspense>\n      <Suspense fallback={<div>Loading posts...</div>}>\n        <ProfilePosts />\n      </Suspense>\n      <Suspense fallback={<div>Loading friends...</div>}>\n        <ProfileFriends />\n      </Suspense>\n    </SuspenseList>\n  );\n}\n*/\n\n// 9. Fallback prioritization\nfunction ProgressiveLoading() {\n  return (\n    <ErrorBoundary>\n      <Suspense fallback={<FullPageSpinner />}>\n        <Layout>\n          <Suspense fallback={<SidebarSkeleton />}>\n            <Sidebar />\n          </Suspense>\n          <MainContent>\n            <Suspense fallback={<ArticleSkeleton />}>\n              <Article />\n            </Suspense>\n            <Suspense fallback={<CommentsSkeleton />}>\n              <Comments />\n            </Suspense>\n          </MainContent>\n        </Layout>\n      </Suspense>\n    </ErrorBoundary>\n  );\n}\n\n// 10. Integration with data fetching libraries\n// Many libraries support Suspense:\n// - React Query: useSuspenseQuery\n// - SWR: useSWR with { suspense: true }\n// - Relay: useLazyLoadQuery with @ suspense\n\n// Example with React Query:\n/*\nimport { useSuspenseQuery } from '@tanstack/react-query';\n\nfunction UserProfile({ userId }) {\n  const { data: user } = useSuspenseQuery({\n    queryKey: ['user', userId],\n    queryFn: () => fetchUser(userId)\n  });\n  \n  return (\n    <div>\n      <h1>{user.name}</h1>\n      <p>{user.email}</p>\n    </div>\n  );\n}\n*/\n```",
