      front:
        'How does React handle forms: controlled vs uncontrolled components, validation, and libraries?',
      back: 'React forms can be controlled (React state) or uncontrolled (DOM state). Key concepts: validation, submission, and integration with form libraries like Formik or React Hook Form.\n\nExample:\n```jsx\n// 1. Controlled Component Form\nfunction ControlledForm() {\n  const [formData, setFormData] = useState({\n    name: \'\',\n    email: \'\',\n    password: \'\'\n  });\n  const [errors, setErrors] = useState({});\n  \n  const handleChange = (e) => {\n    const { name, value } = e.target;\n    setFormData(prev => ({\n      ...prev,\n      [name]: value\n    }));\n    \n    // Clear error when user starts typing\n    if (errors[name]) {\n      setErrors(prev => ({\n        ...prev,\n        [name]: \'\'\n      }));\n    }\n  };\n  \n  const validate = () => {\n    const newErrors = {};\n    \n    if (!formData.name.trim()) {\n      newErrors.name = \'Name is required\';\n    }\n    \n    if (!formData.email.includes(\'@\')) {\n      newErrors.email = \'Valid email is required\';\n    }\n    \n    if (formData.password.length < 6) {\n      newErrors.password = \'Password must be at least 6 characters\';\n    }\n    \n    return newErrors;\n  };\n  \n  const handleSubmit = (e) => {\n    e.preventDefault();\n    \n    const validationErrors = validate();\n    if (Object.keys(validationErrors).length > 0) {\n      setErrors(validationErrors);\n      return;\n    }\n    \n    // Submit form\n    console.log(\'Submitting:\', formData);\n  };\n  \n  return (\n    <form onSubmit={handleSubmit}>\n      <div>\n        <label htmlFor="name">Name:</label>\n        <input\n          id="name"\n          name="name"\n          value={formData.name}\n          onChange={handleChange}\n        />\n        {errors.name && <span className="error">{errors.name}</span>}\n      </div>\n      \n      <div>\n        <label htmlFor="email">Email:</label>\n        <input\n          id="email"\n          name="email"\n          type="email"\n          value={formData.email}\n          onChange={handleChange}\n        />\n        {errors.email && <span className="error">{errors.email}</span>}\n      </div>\n      \n      <div>\n        <label htmlFor="password">Password:</label>\n        <input\n          id="password"\n          name="password"\n          type="password"\n          value={formData.password}\n          onChange={handleChange}\n        />\n        {errors.password && <span className="error">{errors.password}</span>}\n      </div>\n      \n      <button type="submit">Submit</button>\n    </form>\n  );\n}\n\n// 2. Uncontrolled Component Form\nfunction UncontrolledForm() {\n  const formRef = useRef(null);\n  \n  const handleSubmit = (e) => {\n    e.preventDefault();\n    \n    const formData = new FormData(formRef.current);\n    const data = Object.fromEntries(formData.entries());\n    \n    console.log(\'Form data:\', data);\n  };\n  \n  return (\n    <form ref={formRef} onSubmit={handleSubmit}>\n      <input name="username" defaultValue="" />\n      <input name="email" type="email" defaultValue="" />\n      <button type="submit">Submit</button>\n    </form>\n  );\n}\n\n// 3. Custom hook for form management\nfunction useForm(initialValues, validate) {\n  const [values, setValues] = useState(initialValues);\n  const [errors, setErrors] = useState({});\n  const [touched, setTouched] = useState({});\n  const [isSubmitting, setIsSubmitting] = useState(false);\n  \n  const handleChange = (e) => {\n    const { name, value, type, checked } = e.target;\n    \n    setValues(prev => ({\n      ...prev,\n      [name]: type === \'checkbox\' ? checked : value\n    }));\n  };\n  \n  const handleBlur = (e) => {\n    const { name } = e.target;\n    setTouched(prev => ({ ...prev, [name]: true }));\n    \n    // Validate on blur\n    if (validate) {\n      const validationErrors = validate(values);\n      setErrors(validationErrors);\n    }\n  };\n  \n  const handleSubmit = (onSubmit) => (e) => {\n    e.preventDefault();\n    setIsSubmitting(true);\n    \n    if (validate) {\n      const validationErrors = validate(values);\n      setErrors(validationErrors);\n      \n      if (Object.keys(validationErrors).length > 0) {\n        setIsSubmitting(false);\n        return;\n      }\n    }\n    \n    onSubmit(values, { setErrors, setIsSubmitting });\n  };\n  \n  const resetForm = () => {\n    setValues(initialValues);\n    setErrors({});\n    setTouched({});\n    setIsSubmitting(false);\n  };\n  \n  return {\n    values,\n    errors,\n    touched,\n    isSubmitting,\n    handleChange,\n    handleBlur,\n    handleSubmit,\n    resetForm,\n    setValues\n  };\n}\n\n// Usage\nfunction LoginForm() {\n  const validate = (values) => {\n    const errors = {};\n    if (!values.email) errors.email = \'Required\';\n    if (!values.password) errors.password = \'Required\';\n    return errors;\n  };\n  \n  const onSubmit = async (values, { setErrors, setIsSubmitting }) => {\n    try {\n      await loginUser(values);\n      // Redirect or show success\n    } catch (error) {\n      setErrors({ form: error.message });\n    } finally {\n      setIsSubmitting(false);\n    }\n  };\n  \n  const form = useForm({ email: \'\', password: \'\' }, validate);\n  \n  return (\n    <form onSubmit={form.handleSubmit(onSubmit)}>\n      {form.errors.form && (\n        <div className="form-error">{form.errors.form}</div>\n      )}\n      \n      <div>\n        <label>Email:</label>\n        <input\n          name="email"\n          value={form.values.email}\n          onChange={form.handleChange}\n          onBlur={form.handleBlur}\n        />\n        {form.touched.email && form.errors.email && (\n          <span>{form.errors.email}</span>\n        )}\n      </div>\n      \n      <div>\n        <label>Password:</label>\n        <input\n          name="password"\n          type="password"\n          value={form.values.password}\n          onChange={form.handleChange}\n          onBlur={form.handleBlur}\n        />\n        {form.touched.password && form.errors.password && (\n          <span>{form.errors.password}</span>\n        )}\n      </div>\n      \n      <button type="submit" disabled={form.isSubmitting}>\n        {form.isSubmitting ? \'Logging in...\' : \'Login\'}\n      </button>\n    </form>\n  );\n}\n\n// 4. Form with React Hook Form (popular library)\n/*\nimport { useForm } from \'react-hook-form\';\n\nfunction ReactHookFormExample() {\n  const {\n    register,\n    handleSubmit,\n    formState: { errors, isSubmitting }\n  } = useForm();\n  \n  const onSubmit = (data) => console.log(data);\n  \n  return (\n    <form onSubmit={handleSubmit(onSubmit)}>\n      <input\n        {...register(\'name\', { required: true })}\n        placeholder="Name"\n      />\n      {errors.name && <span>Name is required</span>}\n      \n      <input\n        {...register(\'email\', {\n          required: true,\n          pattern: /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/\n        })}\n        placeholder="Email"\n      />\n      {errors.email && <span>Valid email is required</span>}\n      \n      <button type="submit" disabled={isSubmitting}>\n        Submit\n      </button>\n    </form>\n  );\n}\n*/\n\n// 5. Dynamic form fields\nfunction DynamicForm() {\n  const [fields, setFields] = useState([{ id: 1, value: \'\' }]);\n  \n  const addField = () => {\n    setFields(prev => [...prev, { id: Date.now(), value: \'\' }]);\n  };\n  \n  const removeField = (id) => {\n    setFields(prev => prev.filter(field => field.id !== id));\n  };\n  \n  const updateField = (id, value) => {\n    setFields(prev => prev.map(field =>\n      field.id === id ? { ...field, value } : field\n    ));\n  };\n  \n  return (\n    <div>\n      {fields.map(field => (\n        <div key={field.id}>\n          <input\n            value={field.value}\n            onChange={(e) => updateField(field.id, e.target.value)}\n          />\n          <button onClick={() => removeField(field.id)}>Remove</button>\n        </div>\n      ))}\n      <button onClick={addField}>Add Field</button>\n    </div>\n  );\n}\n```',
