      front:
        'What is code splitting in React and how do you implement it with dynamic imports?',
      back: "Code splitting breaks your app into smaller bundles loaded on demand. Implemented via dynamic imports with React.lazy() and Suspense for better performance.\n\nExample:\n```javascript\n// 1. Basic dynamic import with React.lazy\nconst HomePage = React.lazy(() => import('./pages/HomePage'));\nconst AboutPage = React.lazy(() => import('./pages/AboutPage'));\nconst ContactPage = React.lazy(() => import('./pages/ContactPage'));\n\n// 2. Route-based code splitting\nimport { BrowserRouter as Router, Routes, Route } from 'react-router-dom';\n\nfunction App() {\n  return (\n    <Router>\n      <Suspense fallback={<div>Loading page...</div>}>\n        <Routes>\n          <Route path=\"/\" element={<HomePage />} />\n          <Route path=\"/about\" element={<AboutPage />} />\n          <Route path=\"/contact\" element={<ContactPage />} />\n        </Routes>\n      </Suspense>\n    </Router>\n  );\n}\n\n// 3. Component-based splitting\nconst HeavyChart = React.lazy(() => import('./components/HeavyChart'));\nconst RichTextEditor = React.lazy(() => import('./components/RichTextEditor'));\n\nfunction Dashboard() {\n  const [showChart, setShowChart] = useState(false);\n  const [showEditor, setShowEditor] = useState(false);\n  \n  return (\n    <div>\n      <button onClick={() => setShowChart(true)}>Load Chart</button>\n      <button onClick={() => setShowEditor(true)}>Load Editor</button>\n      \n      {showChart && (\n        <Suspense fallback={<div>Loading chart...</div>}>\n          <HeavyChart />\n        </Suspense>\n      )}\n      \n      {showEditor && (\n        <Suspense fallback={<div>Loading editor...</div>}>\n          <RichTextEditor />\n        </Suspense>\n      )}\n    </div>\n  );\n}\n\n// 4. Named exports with dynamic imports\n// Export must be default for React.lazy, but you can work around:\nconst UsersList = React.lazy(() =>\n  import('./components/UsersList')\n    .then(module => ({ default: module.UsersList }))\n);\n\n// Alternative: create a wrapper component\nexport default function UsersListWrapper() {\n  return <UsersList />;\n}\n\n// 5. Preloading components\nfunction PreloadableComponent({ component, children }) {\n  const [isLoaded, setIsLoaded] = useState(false);\n  const [Component, setComponent] = useState(null);\n  \n  const preload = () => {\n    component().then(module => {\n      setComponent(() => module.default);\n      setIsLoaded(true);\n    });\n  };\n  \n  return (\n    <div\n      onMouseEnter={preload} // Preload on hover\n      onClick={preload} // Or on click\n    >\n      {children}\n      \n      {isLoaded && Component && (\n        <Suspense fallback={<div>Loading...</div>}>\n          <Component />\n        </Suspense>\n      )}\n    </div>\n  );\n}\n\n// Usage\n<PreloadableComponent\n  component={() => import('./HeavyComponent')}\n>\n  <button>Show Heavy Component</button>\n</PreloadableComponent>\n\n// 6. Webpack magic comments for better splitting\nconst AdminPanel = React.lazy(() =>\n  import(\n    /* webpackChunkName: \"admin-panel\" */\n    /* webpackPrefetch: true */\n    './pages/AdminPanel'\n  )\n);\n\nconst AnalyticsDashboard = React.lazy(() =>\n  import(\n    /* webpackChunkName: \"analytics\" */\n    /* webpackPreload: true */\n    './components/AnalyticsDashboard'\n  )\n);\n\n// 7. Error handling for failed imports\nfunction withRetry(importFn, retries = 3) {\n  return new Promise((resolve, reject) => {\n    importFn()\n      .then(resolve)\n      .catch((error) => {\n        if (retries > 0) {\n          setTimeout(() => {\n            withRetry(importFn, retries - 1)\n              .then(resolve)\n              .catch(reject);\n          }, 1000);\n        } else {\n          reject(error);\n        }\n      });\n  });\n}\n\nconst ReliableComponent = React.lazy(() =>\n  withRetry(() => import('./UnreliableComponent'))\n);\n\n// 8. Bundle analysis and optimization\n/*\n// Use tools like:\n// - Webpack Bundle Analyzer\n// - Source Map Explorer\n// - Bundle Buddy\n\n// Example webpack config:\nmodule.exports = {\n  optimization: {\n    splitChunks: {\n      chunks: 'all',\n      cacheGroups: {\n        vendor: {\n          test: /[\\\\/]node_modules[\\\\/]/,\n          name: 'vendors',\n          chunks: 'all'\n        },\n        reactBundle: {\n          test: /[\\\\/]node_modules[\\\\/](react|react-dom)[\\\\/]/,\n          name: 'react-bundle',\n          chunks: 'all',\n          priority: 10\n        }\n      }\n    }\n  }\n};\n*/\n\n// 9. Loading state with skeleton screens\nfunction SkeletonLoader() {\n  return (\n    <div className=\"skeleton\">\n      <div className=\"skeleton-header\" />\n      <div className=\"skeleton-content\" />\n      <div className=\"skeleton-content\" />\n      <div className=\"skeleton-content\" />\n    </div>\n  );\n}\n\nfunction LazyComponentWithSkeleton() {\n  return (\n    <Suspense fallback={<SkeletonLoader />}>\n      <HeavyComponent />\n    </Suspense>\n  );\n}\n\n// 10. Progressive loading with intersection observer\nfunction LazyLoadOnViewport({ children, fallback }) {\n  const ref = useRef(null);\n  const [isVisible, setIsVisible] = useState(false);\n  \n  useEffect(() => {\n    const observer = new IntersectionObserver(\n      ([entry]) => {\n        if (entry.isIntersecting) {\n          setIsVisible(true);\n          observer.disconnect();\n        }\n      },\n      { threshold: 0.1 }\n    );\n    \n    if (ref.current) {\n      observer.observe(ref.current);\n    }\n    \n    return () => observer.disconnect();\n  }, []);\n  \n  return (\n    <div ref={ref}>\n      {isVisible ? children : fallback}\n    </div>\n  );\n}\n\n// Usage\n<LazyLoadOnViewport fallback={<div>Not in viewport yet</div>}>\n  <Suspense fallback={<div>Loading...</div>}>\n    <HeavyComponent />\n  </Suspense>\n</LazyLoadOnViewport>\n\n// 11. Measuring performance impact\nfunction useLoadTime(componentName) {\n  const [loadTime, setLoadTime] = useState(null);\n  const startTime = useRef(performance.now());\n  \n  useEffect(() => {\n    const measure = () => {\n      const endTime = performance.now();\n      setLoadTime(endTime - startTime.current);\n      \n      // Send to analytics\n      console.log(`${componentName} loaded in ${loadTime}ms`);\n    };\n    \n    // Simulate component loaded\n    const timer = setTimeout(measure, 100);\n    return () => clearTimeout(timer);\n  }, [componentName]);\n  \n  return loadTime;\n}\n```",
