      front:
        'How do you optimize React performance with useCallback, useMemo, and React.memo?',
      back: "Performance optimization triad: useCallback memoizes functions, useMemo memoizes values, React.memo memoizes components. Use them strategically to prevent unnecessary re-renders and computations.\n\nExample:\n```jsx\n// 1. Identifying performance issues\nfunction ProfilePage({ userId }) {\n  const [user, setUser] = useState(null);\n  const [posts, setPosts] = useState([]);\n  \n  // ❌ Created on every render\n  const fetchUser = async () => {\n    const response = await fetch(`/api/users/${userId}`);\n    setUser(await response.json());\n  };\n  \n  // ❌ Created on every render\n  const fetchPosts = async () => {\n    const response = await fetch(`/api/users/${userId}/posts`);\n    setPosts(await response.json());\n  };\n  \n  // ❌ Calculated on every render\n  const stats = {\n    postCount: posts.length,\n    lastActive: user?.lastLogin\n  };\n  \n  useEffect(() => {\n    fetchUser();\n    fetchPosts();\n  }, [userId, fetchUser, fetchPosts]); // ❌ Infinite loop - new functions each render\n  \n  return (\n    <div>\n      <UserProfile user={user} />\n      <PostList posts={posts} stats={stats} />\n    </div>\n  );\n}\n\n// 2. Optimized version\nfunction OptimizedProfilePage({ userId }) {\n  const [user, setUser] = useState(null);\n  const [posts, setPosts] = useState([]);\n  \n  // ✅ Memoized functions\n  const fetchUser = useCallback(async () => {\n    const response = await fetch(`/api/users/${userId}`);\n    setUser(await response.json());\n  }, [userId]); // Only recreates when userId changes\n  \n  const fetchPosts = useCallback(async () => {\n    const response = await fetch(`/api/users/${userId}/posts`);\n    setPosts(await response.json());\n  }, [userId]);\n  \n  // ✅ Memoized expensive calculation\n  const stats = useMemo(() => ({\n    postCount: posts.length,\n    lastActive: user?.lastLogin,\n    // Complex calculations\n    avgPostLength: posts.reduce((sum, post) => sum + post.content.length, 0) / posts.length || 0\n  }), [posts, user?.lastLogin]); // Only recalculates when dependencies change\n  \n  useEffect(() => {\n    fetchUser();\n    fetchPosts();\n  }, [userId, fetchUser, fetchPosts]); // ✅ Stable dependencies\n  \n  return (\n    <div>\n      <MemoizedUserProfile user={user} />\n      <MemoizedPostList posts={posts} stats={stats} />\n    </div>\n  );\n}\n\n// 3. Memoized components\nconst MemoizedUserProfile = React.memo(({ user }) => {\n  console.log('UserProfile rendered');\n  \n  if (!user) return <div>Loading...</div>;\n  \n  return (\n    <div className=\"user-profile\">\n      <h1>{user.name}</h1>\n      <p>{user.email}</p>\n      <UserStats user={user} />\n    </div>\n  );\n});\n\n// Child components also need optimization\nconst UserStats = React.memo(({ user }) => {\n  console.log('UserStats rendered');\n  \n  // Expensive calculation\n  const activityScore = useMemo(() => {\n    return calculateActivityScore(user.posts, user.comments, user.likes);\n  }, [user.posts, user.comments, user.likes]);\n  \n  return (\n    <div className=\"stats\">\n      <p>Activity Score: {activityScore}</p>\n    </div>\n  );\n});\n\n// 4. When to use each optimization\nfunction OptimizationGuide() {\n  const [count, setCount] = useState(0);\n  const [items, setItems] = useState([]);\n  \n  // ✅ useCallback: When passing function to optimized child\n  const handleClick = useCallback(() => {\n    console.log('Clicked:', count);\n  }, [count]);\n  \n  // ✅ useMemo: Expensive calculations\n  const processedItems = useMemo(() => {\n    return items.map(item => expensiveProcessing(item));\n  }, [items]);\n  \n  // ✅ useMemo: Object/array creation for dependencies\n  const config = useMemo(() => ({\n    maxItems: 10,\n    sortDirection: 'asc'\n  }), []); // Empty array = never changes\n  \n  // ❌ Don't over-optimize\n  const simpleValue = count * 2; // Just calculate it\n  // const simpleValue = useMemo(() => count * 2, [count]); // Overkill\n  \n  return (\n    <div>\n      <button onClick={() => setCount(c => c + 1)}>\n        Count: {count}\n      </button>\n      \n      {/* Child gets stable function reference */}\n      <OptimizedChild onClick={handleClick} data={processedItems} config={config} />\n    </div>\n  );\n}\n\nconst OptimizedChild = React.memo(({ onClick, data, config }) => {\n  console.log('OptimizedChild rendered');\n  \n  return (\n    <div>\n      <button onClick={onClick}>Click me</button>\n      <p>Items: {data.length}</p>\n    </div>\n  );\n});\n\n// 5. Performance measurement\nfunction useRenderCount(componentName) {\n  const renderCount = useRef(0);\n  \n  useEffect(() => {\n    renderCount.current += 1;\n    console.log(`${componentName} rendered: ${renderCount.current} times`);\n  });\n  \n  return renderCount.current;\n}\n\nfunction MeasuredComponent() {\n  const renderCount = useRenderCount('MeasuredComponent');\n  \n  return <div>Rendered {renderCount} times</div>;\n}\n\n// 6. Profiler component for measuring\nfunction ProfilerExample() {\n  return (\n    <React.Profiler\n      id=\"Navigation\"\n      onRender={(\n        id, // \"Navigation\"\n        phase, // \"mount\" or \"update\"\n        actualDuration, // Time spent rendering\n        baseDuration, // Estimated time without memoization\n        startTime, // When render started\n        commitTime // When update was committed\n      ) => {\n        console.log(`\\n--- ${id} ---`);\n        console.log(`Phase: ${phase}`);\n        console.log(`Actual: ${actualDuration.toFixed(2)}ms`);\n        console.log(`Base: ${baseDuration.toFixed(2)}ms`);\n        \n        if (actualDuration > 16) { // 60fps = 16ms per frame\n          console.warn('Slow render detected!');\n        }\n      }}\n    >\n      <Navigation />\n    </React.Profiler>\n  );\n}\n\n// 7. Virtualization for large lists\n/*\nimport { FixedSizeList as List } from 'react-window';\n\nfunction LargeList({ items }) {\n  return (\n    <List\n      height={400}\n      itemCount={items.length}\n      itemSize={50}\n      width={300}\n    >\n      {({ index, style }) => (\n        <div style={style}>\n          Item {index}: {items[index].name}\n        </div>\n      )}\n    </List>\n  );\n}\n*/\n\n// 8. Debouncing and throttling expensive operations\nfunction SearchInput() {\n  const [query, setQuery] = useState('');\n  const [results, setResults] = useState([]);\n  \n  // Debounced search\n  const debouncedSearch = useMemo(() => \n    debounce(async (searchQuery) => {\n      if (searchQuery) {\n        const response = await fetch(`/api/search?q=${searchQuery}`);\n        setResults(await response.json());\n      } else {\n        setResults([]);\n      }\n    }, 300)\n  , []);\n  \n  useEffect(() => {\n    debouncedSearch(query);\n    \n    return () => {\n      debouncedSearch.cancel();\n    };\n  }, [query, debouncedSearch]);\n  \n  return (\n    <div>\n      <input\n        value={query}\n        onChange={(e) => setQuery(e.target.value)}\n        placeholder=\"Search...\"\n      />\n      <SearchResults results={results} />\n    </div>\n  );\n}\n\nconst SearchResults = React.memo(({ results }) => {\n  return (\n    <ul>\n      {results.map(result => (\n        <li key={result.id}>{result.name}</li>\n      ))}\n    </ul>\n  );\n});\n```",
