      front:
        'What are React Server Components and how do they differ from Client Components?',
      back: "React Server Components run on the server, can access backend resources directly, and reduce bundle size. Client Components run in the browser and are interactive.\n\nExample:\n```jsx\n// Note: Server Components are experimental (React 18+)\n// This shows the conceptual difference\n\n// 1. Server Component (runs on server)\n// ServerComponent.js - Note: .server.js extension\nasync function ProductPage({ productId }) {\n  // ✅ Direct database access (server-only)\n  const product = await db.products.findUnique({ where: { id: productId } });\n  \n  // ✅ Server-side data fetching\n  const reviews = await fetchReviews(productId);\n  \n  // ✅ No React state or effects\n  // ❌ Cannot use useState, useEffect, etc.\n  \n  // ✅ Can import Server Components\n  const Recommendations = await import('./Recommendations.server.js');\n  \n  return (\n    <div>\n      <h1>{product.name}</h1>\n      <p>{product.description}</p>\n      \n      {/* Client Component for interactivity */}\n      <AddToCart productId={productId} />\n      \n      {/* Server Component */}\n      <Recommendations productId={productId} />\n      \n      {/* Async data in Server Component */}\n      <ReviewsList reviews={reviews} />\n    </div>\n  );\n}\n\n// 2. Client Component (runs in browser)\n// AddToCart.js - Note: 'use client' directive\n'use client';\n\nimport { useState } from 'react';\n\nexport default function AddToCart({ productId }) {\n  // ✅ Client-side state\n  const [quantity, setQuantity] = useState(1);\n  const [isLoading, setIsLoading] = useState(false);\n  \n  // ✅ Event handlers\n  const handleAddToCart = async () => {\n    setIsLoading(true);\n    try {\n      await fetch('/api/cart', {\n        method: 'POST',\n        body: JSON.stringify({ productId, quantity })\n      });\n      // Show success message\n    } catch (error) {\n      // Handle error\n    } finally {\n      setIsLoading(false);\n    }\n  };\n  \n  // ✅ Effects\n  useEffect(() => {\n    // Subscribe to cart updates\n  }, []);\n  \n  return (\n    <div>\n      <input\n        type=\"number\"\n        value={quantity}\n        onChange={(e) => setQuantity(parseInt(e.target.value))}\n        min=\"1\"\n      />\n      <button onClick={handleAddToCart} disabled={isLoading}>\n        {isLoading ? 'Adding...' : 'Add to Cart'}\n      </button>\n    </div>\n  );\n}\n\n// 3. Shared Component (can be used on both)\n// PriceDisplay.js - No 'use client' directive\n// This is a Server Component by default\n// But can be imported by Client Components if they don't use server-only features\nexport default function PriceDisplay({ price, currency = 'USD' }) {\n  const formattedPrice = new Intl.NumberFormat('en-US', {\n    style: 'currency',\n    currency\n  }).format(price);\n  \n  return <span className=\"price\">{formattedPrice}</span>;\n}\n\n// 4. Data fetching patterns\n// Server Component with streaming\nasync function ProductReviews({ productId }) {\n  // Slow database query\n  const reviews = await fetchReviews(productId);\n  \n  // Stream the result\n  return (\n    <Suspense fallback={<div>Loading reviews...</div>}>\n      <ReviewsList reviews={reviews} />\n    </Suspense>\n  );\n}\n\n// 5. Composition example\n// App.server.js\nasync function App() {\n  return (\n    <html>\n      <body>\n        <Header />\n        <main>\n          {/* Server Components */}\n          <ProductListing />\n          <Sidebar />\n          \n          {/* Interactive parts as Client Components */}\n          <SearchBar />\n          <UserMenu />\n        </main>\n        <Footer />\n      </body>\n    </html>\n  );\n}\n\n// 6. Server Actions (React 19+)\n// Form with server action\n'use server';\n\nexport async function createPost(formData) {\n  // Server-side validation\n  const title = formData.get('title');\n  const content = formData.get('content');\n  \n  if (!title || !content) {\n    throw new Error('Title and content required');\n  }\n  \n  // Direct database access\n  const post = await db.post.create({\n    data: { title, content }\n  });\n  \n  return post;\n}\n\n// Client Component using server action\n'use client';\n\nexport default function CreatePostForm() {\n  return (\n    <form action={createPost}>\n      <input name=\"title\" placeholder=\"Title\" />\n      <textarea name=\"content\" placeholder=\"Content\" />\n      <button type=\"submit\">Create Post</button>\n    </form>\n  );\n}\n\n// 7. Benefits of Server Components:\n// - Smaller bundle size (server-only code not shipped)\n// - Direct backend access\n// - Improved security (secrets stay on server)\n// - Better SEO (content rendered on server)\n\n// 8. When to use each:\n// Server Components:\n// - Static content\n// - Data fetching\n// - Non-interactive UI\n// - Heavy dependencies\n\n// Client Components:\n// - Interactive elements\n// - Browser APIs\n// - State and effects\n// - Event handlers\n\n// 9. Migration strategy\n// Before: All components in client bundle\nfunction OldProductPage({ productId }) {\n  const [product, setProduct] = useState(null);\n  const [reviews, setReviews] = useState([]);\n  \n  useEffect(() => {\n    fetchProduct(productId).then(setProduct);\n    fetchReviews(productId).then(setReviews);\n  }, [productId]);\n  \n  return (\n    <div>\n      {product && (\n        <>\n          <h1>{product.name}</h1>\n          <p>{product.description}</p>\n        </>\n      )}\n      <AddToCart productId={productId} />\n      <ReviewsList reviews={reviews} />\n    </div>\n  );\n}\n\n// After: Split into Server and Client Components\n// ProductPage.server.js\nasync function NewProductPage({ productId }) {\n  const product = await fetchProduct(productId);\n  const reviews = await fetchReviews(productId);\n  \n  return (\n    <>\n      <h1>{product.name}</h1>\n      <p>{product.description}</p>\n      <AddToCart productId={productId} />\n      <ReviewsList reviews={reviews} />\n    </>\n  );\n}\n\n// 10. Error boundaries still work\n// ErrorBoundary.client.js\n'use client';\n\nexport class ErrorBoundary extends React.Component {\n  // Same as before\n}\n\n// Usage in Server Component\n<ErrorBoundary>\n  <ProductPage productId={productId} />\n</ErrorBoundary>\n```",
